def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data")
    if not isinstance(data, list) or len(data) == 0:
        raise Blocked("no community available")
    return statusCode == 200 and responseBody.get("code") == 0 and all(item.get("id") and item.get("name") for item in data) and bool(responseBody.get("requestId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data")
    if not isinstance(data, dict):
        return False
    exp = data.get("expires_in")
    wait = data.get("next_send_after")
    return statusCode == 200 and responseBody.get("code") == 0 and isinstance(exp, int) and not isinstance(exp, bool) and exp > 0 and isinstance(wait, int) and not isinstance(wait, bool) and wait > 0 and "code" not in data and bool(responseBody.get("requestId"))
